def main():
    data = base64.b64decode(IMAGE_B64)
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        print("embedded image failed sha256 check", file=sys.stderr)
        return 1
    os.makedirs(os.path.dirname(DEST), exist_ok=True)
    with open(DEST, "wb") as f:
        f.write(data)
    # Read-back check: the output must be byte-identical to the
    # embedded image.
    with open(DEST, "rb") as f:
        actual = f.read()
    if actual != data:
        print("output does not match embedded image", file=sys.stderr)
        return 1
    if hashlib.sha256(actual).hexdigest() != EXPECTED_SHA256:
        print("output failed sha256 check", file=sys.stderr)
        return 1
    print(f"wrote {DEST} ({len(actual)} bytes, sha256 {EXPECTED_SHA256})")
    return 0


if __name__ == "__main__":
    sys.exit(main())
